CREATE OR REPLACE FUNCTION public.simulate_credit_purchase(p_package_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ DECLARE v_user_id uuid := auth.uid(); v_credits integer; v_package_name text; v_price text; v_balance integer; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; CASE p_package_code WHEN 'basico' THEN v_credits := 100; v_package_name := 'Pacote Básico'; v_price := 'R$ 4,90'; WHEN 'pro' THEN v_credits := 350; v_package_name := 'Pacote Pró'; v_price := 'R$ 14,90'; WHEN 'mega' THEN v_credits := 1000; v_package_name := 'Pacote Mega'; v_price := 'R$ 34,90'; ELSE RAISE EXCEPTION 'Pacote de créditos inválido'; END CASE; INSERT INTO public.credit_wallets (user_id) VALUES (v_user_id) ON CONFLICT (user_id) DO NOTHING; INSERT INTO public.credit_transactions (user_id, amount, transaction_type, description, metadata) VALUES (v_user_id, v_credits, 'simulated_purchase', v_package_name || ' (simulação)', jsonb_build_object('package_code', p_package_code, 'display_price', v_price)); UPDATE public.credit_wallets AS cw SET balance = cw.balance + v_credits, lifetime_earned = cw.lifetime_earned + v_credits, updated_at = now() WHERE cw.user_id = v_user_id RETURNING cw.balance INTO v_balance; RETURN jsonb_build_object('package_code', p_package_code, 'credits', v_credits, 'balance', v_balance, 'simulated', true); END; $$;